def extract(
    self,
    carrier: textmap.CarrierT,
    context: Context | None = None,
    getter: textmap.Getter[textmap.CarrierT] = textmap.default_getter,
) -> Context:
    """Extracts SpanContext from the carrier.

    See `opentelemetry.propagators.textmap.TextMapPropagator.extract`
    """
    if context is None:
        context = Context()

    header = getter.get(carrier, self._TRACEPARENT_HEADER_NAME)

    if not header:
        return context

    value = header[0]
    if type(value) is str and len(value) == 55 and value.startswith("00-") and value[35] == "-" and value[52] == "-":
        if not value.isascii() or value.lower() != value:
            return context
        trace_id = value[3:35]
        span_id = value[36:52]
        trace_flags = value[53:55]
        if not (trace_id.isalnum() and span_id.isalnum() and trace_flags.isalnum()):
            return context
        try:
            trace_id = int(trace_id, 16)
            span_id = int(span_id, 16)
            trace_flags = int(trace_flags, 16)
        except ValueError:
            return context
    else:
        match = self._TRACEPARENT_HEADER_FORMAT_RE.search(value)
        if not match:
            return context
        version, trace_id, span_id, trace_flags, suffix = match.groups()
        if version == "ff" or (version == "00" and suffix):
            return context
        trace_id = int(trace_id, 16)
        span_id = int(span_id, 16)
        trace_flags = int(trace_flags, 16)
    if not trace_id or not span_id:
        return context

    tracestate_headers = getter.get(carrier, self._TRACESTATE_HEADER_NAME)
    if tracestate_headers is None:
        tracestate = None
    elif (
        # multiple header fields are combined with "," (RFC 9110, section 5.3)
        sum(len(header) for header in tracestate_headers) + len(tracestate_headers) - 1
        > _TRACECONTEXT_MAXIMUM_TRACESTATE_LENGTH
    ):
        _logger.warning(
            "tracestate header exceeded the maximum length of %d characters",
            _TRACECONTEXT_MAXIMUM_TRACESTATE_LENGTH,
        )
        tracestate = None
    else:
        tracestate = TraceState.from_header(tracestate_headers)

    span_context = trace.SpanContext(
        trace_id=trace_id,
        span_id=span_id,
        is_remote=True,
        trace_flags=trace.TraceFlags(trace_flags),
        trace_state=tracestate,
    )
    return trace.set_span_in_context(trace.NonRecordingSpan(span_context), context)

